"""Render a pipeline result as a Markdown requirements document."""


def _ids(ids):
    return f" `{', '.join(ids)}`" if ids else ""


def to_markdown(r: dict) -> str:
    if r.get("status") != "ok":
        return f"# Not analysed\n\n{r.get('gate', {}).get('reason', '')}\n"
    L = ["# Software Requirements (draft)", "",
         "> Generated by Reqnova (AI for Requirements). Items marked *assumption* or listed under "
         "Missing information must be confirmed with the customer.", "",
         "## 1. Problem statement", "", r["problem_statement"], "",
         "## 2. Actors", ""]
    L += [f"- **{a['name']}** - {a.get('description', '')}{_ids(a['source_ids'])}" for a in r["actors"]]
    for title, key in (("3. Functional requirements", "functional_requirements"),
                       ("4. Non-functional requirements", "non_functional_requirements")):
        L += ["", f"## {title}", ""]
        if not r[key]:
            L.append("_None stated by the customer._")
        for q in r[key]:
            flag = f" ⚠ {'; '.join(q['validation_notes'])}" if q["validation_notes"] else ""
            L.append(f"- **{q['id']}** ({q['origin']}, {q['support']}) {q['text']}{_ids(q['source_ids'])}{flag}")
    L += ["", "## 5. User stories & acceptance criteria", ""]
    for u in r["user_stories"]:
        L.append(f"### {u['id']} - As a {u['as_a']}, I want {u['i_want']}, so that {u['so_that']}")
        L.append(f"Implements: {', '.join(u['requirement_ids']) or '-'}")
        L += [f"- [ ] {c}" for c in u["acceptance_criteria"]]
        L.append("")
    L += ["## 6. Missing information", ""]
    L += [f"- **{m['topic']}** ({m['impact']}): {m['detail']}" for m in r["missing_information"]]
    L += ["", "## 7. Clarifying questions", ""]
    L += [f"{i}. [{q['priority']}] {q['question']} - _{q['why_it_matters']}_"
          for i, q in enumerate(r["clarifying_questions"], 1)]
    L += ["", "## 8. Edge cases", ""]
    L += [f"- {e['scenario']} → {e['expected_handling']}{_ids(e['source_ids'])}" for e in r["edge_cases"]]
    L += ["", "## 9. Assumptions (to confirm)", ""]
    L += [f"- {a['statement']} - {a['reason']}" for a in r["assumptions"]]
    L += ["", "## Appendix: source sentences", ""]
    L += [f"- **{s['id']}** {s['text']}" for s in r["sentences"]]
    return "\n".join(L) + "\n"
